import { Column, CreateDateColumn, Entity, JoinColumn, ManyToOne, PrimaryGeneratedColumn, UpdateDateColumn } from "typeorm";
import { Incident } from "../../incidents/entities/incident.entity";
import { AssignmentGroup } from "../../assignment-group/entities/assignment-group.entity";
import { User } from "../../users/entities/user.entity";

export type WorkOrderStatus = "Open" | "In Progress" | "On Hold" | "Completed" | "Cancelled";

@Entity("work_orders")
export class WorkOrder {
  @PrimaryGeneratedColumn({ name: "work_order_id" }) workOrderId!: number;
  // Generated by the database default (sequence) — never set from the app.
  @Column({ name: "wo_number", insert: false, update: false }) woNumber!: string;

  @ManyToOne(() => Incident, { nullable: true, onDelete: "SET NULL", eager: true })
  @JoinColumn({ name: "incident_id" }) incident?: Incident | null;

  @Column() title!: string;
  @Column({ type: "text", nullable: true }) notes?: string | null;

  @ManyToOne(() => AssignmentGroup, { nullable: true, onDelete: "SET NULL", eager: true })
  @JoinColumn({ name: "group_id" }) group?: AssignmentGroup | null;

  @ManyToOne(() => User, { nullable: true, onDelete: "SET NULL", eager: true })
  @JoinColumn({ name: "assigned_to" }) assignedTo?: User | null;

  @Column({ default: "P3 - Medium" }) priority!: string;
  @Column({ default: "Open" }) status!: WorkOrderStatus;
  @Column({ name: "is_active", default: true }) isActive!: boolean;

  @ManyToOne(() => User, { nullable: true, onDelete: "SET NULL" })
  @JoinColumn({ name: "created_by" }) createdBy?: User | null;

  @CreateDateColumn({ name: "created_at" }) createdAt!: Date;
  @UpdateDateColumn({ name: "updated_at" }) updatedAt!: Date;
}
